import{_ as a,I as i,g as t,j as n}from"./chunks/framework.YqoK2ckR.js";const c=JSON.parse('{"title":"工作空间和功能包","description":"","frontmatter":{},"headers":[],"relativePath":"notes/ROS2/03-工作空间和功能包.md","filePath":"notes/ROS2/03-工作空间和功能包.md"}'),e={name:"notes/ROS2/03-工作空间和功能包.md"};function p(l,s,h,o,d,k){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="工作空间和功能包" tabindex="-1">工作空间和功能包 <a class="header-anchor" href="#工作空间和功能包" aria-label="Permalink to &quot;工作空间和功能包&quot;">​</a></h1><h2 id="什么是工作空间-workspace" tabindex="-1">什么是工作空间(workspace) <a class="header-anchor" href="#什么是工作空间-workspace" aria-label="Permalink to &quot;什么是工作空间(workspace)&quot;">​</a></h2><p>你不能直接打开你linux的根目录终端运行ros2，你的系统盘会爆的</p><p><strong>工作空间：</strong> 其实就是新建文件夹，终端也在这里打开，所有文件都应该放在这里</p><h3 id="典型的ros2文件结构" tabindex="-1">典型的ROS2文件结构 <a class="header-anchor" href="#典型的ros2文件结构" aria-label="Permalink to &quot;典型的ROS2文件结构&quot;">​</a></h3><ul><li>src:存放代码</li><li>install:安装空间，编译出的可执行文件等有效产物会放在这里</li><li>build: 编译空间，存放编译产生的中间文件，这个体积最大</li><li>log：放日志的</li></ul><h3 id="创建一个工作空间" tabindex="-1">创建一个工作空间 <a class="header-anchor" href="#创建一个工作空间" aria-label="Permalink to &quot;创建一个工作空间&quot;">​</a></h3><p>手动创建你的总文件夹，我这里就叫它<code>studyProject</code>,然后进入它，手动创建<code>src</code> 文件夹</p><p>在<code>src</code> 文件夹里打开终端，由于Ubuntu会阻止你用pip全局安装包，所以我们为了下载国内开发者专用的<code>rosdepc</code> 需要先创建虚拟环境：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rosdepc</span></span></code></pre></div><p>等待rosdepc下载完成</p><p>然后运行(不需要sudo!)</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosdepc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosdepc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>我们再回到项目根目录：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span></code></pre></div><p>此后只要在项目根目录下运行这个命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosdepc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rosdistro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> humble</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><p>就会自动安装所有依赖。你可以类比：这个rosdepc就好比npm install从package.json里自动读取要安装的依赖然后自动给你装好</p><p>然后是colcon,之后编译都用它：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3-colcon-ros</span></span></code></pre></div><p>以后编译就用</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">colcon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>就会给你编译了，编译完成就会自动给你生成剩下三个文件夹</p><h2 id="功能包" tabindex="-1">功能包 <a class="header-anchor" href="#功能包" aria-label="Permalink to &quot;功能包&quot;">​</a></h2><p>功能包，就是ROS2世界里组织代码的<strong>最小单元</strong>和**“集装箱”<strong>。你可以把它理解成一个专门用来存放某个具体功能（比如控制底盘、处理摄像头图像、做导航规划）所有相关文件的</strong>专属文件夹**。</p><h3 id="为什么需要功能包" tabindex="-1">为什么需要功能包 <a class="header-anchor" href="#为什么需要功能包" aria-label="Permalink to &quot;为什么需要功能包&quot;">​</a></h3><p>想象一下，如果不区分功能包，把所有代码都堆在一起，当你想要分享其中一个很棒的功能（比如一个激光雷达驱动）时，就得在一大坨代码里费力地剥离出来。别人拿到你的代码，也得面对一锅乱炖。</p><p>ROS2社区的数万个功能包都遵循同样的结构，这让你能快速上手别人的代码，也让工具可以自动化地处理它们。</p><h3 id="功能包的一般配置" tabindex="-1">功能包的一般配置 <a class="header-anchor" href="#功能包的一般配置" aria-label="Permalink to &quot;功能包的一般配置&quot;">​</a></h3><p>一个文件夹是不是ROS2功能包，看它有没有<strong>两个“身份证”</strong> ：</p><ul><li><strong><code>package.xml</code></strong>：<strong>“自我介绍”</strong>。包含这个包的名称、版本、作者、描述，最重要的是它<strong>依赖哪些别的功能包</strong>。</li><li><strong><code>CMakeLists.txt</code></strong> （C++包） 或 <strong><code>setup.py</code></strong> （Python包）：<strong>“编译说明书”</strong>。告诉编译系统（colcon）这个包该如何处理，生成什么可执行文件。</li></ul><p>除了这两个核心文件，一个典型的功能包还常常包含以下文件夹：</p><ul><li><strong><code>src/</code></strong>：存放C++源代码（<code>.cpp</code>文件）。</li><li><strong><code>&lt;package_name&gt;/</code></strong>：存放Python源代码（<code>.py</code>文件），与包名同名。</li><li><strong><code>msg/</code></strong> 和 <strong><code>srv/</code></strong> ：存放自定义的通信接口（消息和服务）。</li><li><strong><code>launch/</code></strong>：存放启动文件，可以一键启动这个包需要的多个节点。</li><li><strong><code>config/</code></strong>：存放参数配置文件（<code>.yaml</code>文件）。</li></ul><p>你可以用命令 <code>ros2 pkg list</code> 列出系统里所有功能包，用 <code>ros2 pkg executables &lt;package_name&gt;</code> 查看某个包里有哪些可执行文件</p><h3 id="功能包创建-构建-运行" tabindex="-1">功能包创建，构建，运行 <a class="header-anchor" href="#功能包创建-构建-运行" aria-label="Permalink to &quot;功能包创建，构建，运行&quot;">​</a></h3><p>创建功能包要先cd到src目录</p><p>格式为<code>ros2 pkg create --build-type &lt;build-type&gt; &lt;package_name&gt;</code></p><p>其中<code>build-type</code> 是功能包类型，有C++和Python两种，对应<code>ament_cmake</code> <code>ament_python</code></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 创建一个C++包</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ament_cmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_cpp_pkg</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 创建一个Python包</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build-type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ament_python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_python_pkg</span></span></code></pre></div><p><strong>构建</strong>先返回项目根目录</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">colcon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 编译工作空间里所有的包</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">colcon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --packages-select</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_python_pkg</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 只编译指定的包</span></span></code></pre></div><p>C++会先编译再构建，python则不需要先编译。</p><p><strong>运行</strong>：编译成功后，先“激活”工作空间，然后就可以运行包里的程序了：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 激活工作空间</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install/setup.bash</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 运行包里的可执行文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_python_pkg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_node</span></span></code></pre></div>`,44)])])}const g=a(e,[["render",p]]);export{c as __pageData,g as default};
